import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';import '../Models/carpenters_model.dart';import '../Models/get_all_services_model.dart';class  CarpenterServicesSources { static Future<List<GetAllServicesModel>> getAllServices()async{  final response = await DioHelper.getData(path:ApiEndpoints.allCarpentryServices ) ;  return (response.data["data"]["services"] as List).map((e) => GetAllServicesModel.fromJson(e)).toList();}static Future<List<CarpentersModel>> getCarpenters()async{  final response = await DioHelper.getData(path:ApiEndpoints.carpenters ) ;  return (response.data["data"]["carpenters"] as List).map((e) => CarpentersModel.fromJson(e)).toList();}}